<script setup>import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{api}from'../api';const router=useRouter(),loading=ref(false),form=reactive({username:'',password:''});async function submit(){loading.value=true;try{const r=await api.login(form);localStorage.setItem('admin_token',r.token);router.push('/dashboard')}finally{loading.value=false}}</script>
<template><div class="login-page"><div class="login-card"><h1>丽水湾</h1><p>会员与门店运营管理中心</p><el-form @submit.prevent="submit"><el-form-item><el-input v-model="form.username" size="large" placeholder="管理员账号" autocomplete="username"/></el-form-item><el-form-item><el-input v-model="form.password" size="large" type="password" show-password placeholder="密码" autocomplete="current-password" @keyup.enter="submit"/></el-form-item><el-button type="primary" :loading="loading" @click="submit">安全登录</el-button></el-form><small class="muted">仅授权工作人员使用，操作均会记录审计日志</small></div></div></template>
